"""A deliberately bad Dockerfile, so `layerlint demo` is worth one command.

Every line is a pattern seen in the wild. `tests/test_demo.py` asserts the demo
still triggers every rule in the registry, so this file cannot rot — if a rule
stops firing here, the build fails.
"""

from __future__ import annotations

from pathlib import Path

DEMO_DOCKERFILE = """\
# layerlint demo — every line here is intentional.
# Generated by `layerlint demo`; safe to delete.

FROM ubuntu:latest AS build

RUN apt-get update
RUN apt-get install -y curl git python3
RUN pip install requests
RUN npm install express

ARG BUILD_TOKEN=ghp_0123456789012345678901234567890abcdefg
ENV API_KEY=AKIAIOSFODNN7EXAMPLE

USER root
RUN sudo apt-get install -y build-essential

RUN curl -fsSL https://get.example.io/install.sh | bash
RUN curl -o /tmp/tool https://example.io/tool && chmod +x /tmp/tool && /tmp/tool
ADD https://example.io/app.tar.gz /opt/app.tar.gz
ADD http://mirror.example.io/toolchain.tar.gz /opt/toolchain.tar.gz
ADD ./vendor.tar.gz /vendor

RUN pip install --trusted-host pypi.internal.example internal-cli

COPY .env /app/.env
COPY id_rsa /root/.ssh/id_rsa
COPY . /app

RUN echo "token=$BUILD_TOKEN" > /app/deploy-credentials
RUN chmod -R 777 /app
RUN rm -rf /var/lib/apt/lists/*
RUN rm -rf /app/cache

WORKDIR app
EXPOSE 22
EXPOSE 8080

RUN apk add curl 2>/dev/null || true

CMD python3 -m http.server
CMD ["python3", "-m", "http.server"]
ENTRYPOINT /entrypoint.sh
ENTRYPOINT ["/entrypoint.sh"]

FROM ubuntu:latest
COPY --from=build /app /app
"""


def write_demo(path: str | Path, force: bool = False) -> Path:
    """Write the demo Dockerfile and return its path.

    Refuses to overwrite unless ``force``: a demo that silently clobbers a real
    Dockerfile is not a demo, it is a data-loss bug.
    """
    target = Path(path)
    # `layerlint demo` (default: a directory called layerlint-demo) must create
    # the directory; `layerlint demo Dockerfile` must write that exact file.
    looks_like_a_directory = target.is_dir() or (
        not target.exists()
        and target.suffix == ""
        and target.name.lower() not in ("dockerfile", "containerfile")
    )
    if looks_like_a_directory:
        target = target / "Dockerfile"
    if target.exists() and not force:
        raise FileExistsError(f"{target} already exists (use --force to overwrite)")
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(DEMO_DOCKERFILE, encoding="utf-8")
    return target
